#!/usr/bin/env bash
# fetch-corpus.sh - download the Tlaku stress-test corpus (real-world SVG, DXF,
# PDF, AI, raster images, G-code, HPGL and LightBurn projects).
#
# Usage:  scripts/fetch-corpus.sh [DEST_DIR]
#   DEST_DIR defaults to <repo>/tests/corpus-downloaded. It must NOT be inside
#   tests/corpus/ (that directory is the small, versioned CC0/public-domain set).
#
# Environment:
#   CORPUS_ONLY="svg dxf"   only fetch these categories (space separated)
#   CORPUS_SKIP_BIG=1       skip files larger than 20 MB
#   CORPUS_CONTACT=URL      contact URL/e-mail put in the User-Agent (Wikimedia policy)
#
# What it does:
#   * downloads every file of the embedded list with curl (-L --fail --retry),
#     unless it is already present with the right sha256;
#   * verifies the sha256 of every file; exits non-zero on any mismatch or
#     download failure;
#   * writes LICENSES.tsv and README.txt in DEST_DIR (license, author, page URL).
#
# LICENSE WARNING: the corpus mixes licenses. Entries marked "scratchpad only"
# (GPL: LibreCAD, LinuxCNC, Universal G-Code Sender, chiplotle) and the CC BY-SA
# entries are for local measurement only. NEVER commit DEST_DIR to the repo and
# never redistribute it. Nothing downloaded is executed or interpreted by this
# script. Requires only: bash, curl, awk, and shasum (or sha256sum).
#
# List columns (tab separated): path, category, url, license, author, sha256, page

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
DEST="${1:-$REPO_ROOT/tests/corpus-downloaded}"
# Wikimedia asks for a descriptive User-Agent with contact info (generic agents get HTTP 429).
UA="TlakuCorpusFetch/1.0 (+${CORPUS_CONTACT:-https://github.com/jahziel1}; open source test corpus downloader)"

mkdir -p "$DEST"
DEST="$(cd "$DEST" && pwd)"

case "$DEST/" in
  */tests/corpus/*)
    echo "error: DEST must not be inside tests/corpus/ (versioned files): $DEST" >&2
    exit 2
    ;;
esac

if command -v shasum >/dev/null 2>&1; then
  sha256() { shasum -a 256 "$1" | awk '{print $1}'; }
elif command -v sha256sum >/dev/null 2>&1; then
  sha256() { sha256sum "$1" | awk '{print $1}'; }
else
  echo "error: need shasum or sha256sum" >&2
  exit 2
fi

filesize() { wc -c < "$1" | awk '{print $1}'; }

LIST="$(mktemp "${TMPDIR:-/tmp}/tlaku-corpus-list.XXXXXX")"
trap 'rm -f "$LIST"' EXIT

cat > "$LIST" <<'CORPUS_LIST_EOF'
