CORPUS_LIST_EOF

n_total=0; n_down=0; n_present=0; n_fail=0; n_badsha=0; n_skip=0
FAILED=""

printf 'path\tcategory\turl\tlicense\tauthor\tsha256\tpage\n' > "$DEST/LICENSES.tsv.tmp"

while IFS=$'\t' read -r rel cat url lic author want page; do
  [ -n "$rel" ] || continue
  n_total=$((n_total + 1))

  case "$rel" in
    /*|*..*) echo "error: unsafe path in list: $rel" >&2; exit 2 ;;
  esac

  if [ -n "${CORPUS_ONLY:-}" ]; then
    case " $CORPUS_ONLY " in
      *" $cat "*) ;;
      *) n_skip=$((n_skip + 1)); continue ;;
    esac
  fi

  dst="$DEST/$rel"
  mkdir -p "$(dirname "$dst")"
  printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$rel" "$cat" "$url" "$lic" "$author" "$want" "$page" \
    >> "$DEST/LICENSES.tsv.tmp"

  if [ -f "$dst" ] && [ "$(sha256 "$dst")" = "$want" ]; then
    n_present=$((n_present + 1))
    continue
  fi
  rm -f "$dst"

  if [ -n "${CORPUS_SKIP_BIG:-}" ]; then
    # cheap size probe via HEAD; skip when > 20 MB
    len="$(curl -sIL --max-time 30 -A "$UA" "$url" 2>/dev/null | awk 'tolower($1)=="content-length:"{v=$2} END{gsub(/\r/,"",v); print v+0}')"
    if [ "${len:-0}" -gt 20971520 ]; then
      echo "skip (big) $rel"
      n_skip=$((n_skip + 1))
      continue
    fi
  fi

  part="$dst.part"
  echo "download $rel"
  ok=0
  attempt=1
  while [ "$attempt" -le 6 ]; do
    if curl -sSL --fail --retry 2 --retry-delay 8 --connect-timeout 30 --max-time 900 \
         -A "$UA" -o "$part" "$url"; then
      ok=1
      break
    fi
    rm -f "$part"
    # HTTP 429 / transient errors (Wikimedia rate limits): back off and retry
    wait=$((attempt * 20))
    echo "  attempt $attempt failed for $rel, retrying in ${wait}s" >&2
    sleep "$wait"
    attempt=$((attempt + 1))
  done
  if [ "$ok" -ne 1 ]; then
    echo "FAILED download: $rel ($url)" >&2
    n_fail=$((n_fail + 1))
    FAILED="$FAILED$rel (download)\n"
    continue
  fi

  got="$(sha256 "$part")"
  if [ "$got" != "$want" ]; then
    echo "SHA256 MISMATCH: $rel" >&2
    echo "  expected $want" >&2
    echo "  got      $got" >&2
    rm -f "$part"
    n_badsha=$((n_badsha + 1))
    FAILED="$FAILED$rel (sha256)\n"
    continue
  fi
  mv "$part" "$dst"
  n_down=$((n_down + 1))

  case "$url" in
    *wikimedia.org*) sleep 5 ;;   # be polite with Wikimedia servers
  esac
done < "$LIST"

mv "$DEST/LICENSES.tsv.tmp" "$DEST/LICENSES.tsv"

{
  echo "Tlaku stress-test corpus"
  echo "========================"
  echo
  echo "Downloaded by scripts/fetch-corpus.sh. License, author and source page of"
  echo "every file are in LICENSES.tsv (columns: path, category, url, license,"
  echo "author, sha256, page)."
  echo
  echo "The corpus mixes licenses (public domain, CC0, CC BY, CC BY-SA, MIT,"
  echo "Apache-2.0, MPL-2.0, GPL, ...). Entries whose license column says"
  echo "'scratchpad only' are GPL: use them for local measurement only. Do not"
  echo "commit this directory to the repository and do not redistribute it."
  echo "Wikimedia Commons attribution requirements (CC BY / CC BY-SA) apply if"
  echo "any of these files is ever shown or republished."
} > "$DEST/README.txt"

echo
echo "corpus summary: total=$n_total downloaded=$n_down already_present=$n_present skipped=$n_skip failed=$n_fail sha_mismatch=$n_badsha"
echo "destination: $DEST"
if [ "$n_fail" -gt 0 ] || [ "$n_badsha" -gt 0 ]; then
  printf 'problems:\n%b' "$FAILED" >&2
  exit 1
fi
exit 0
